import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type PingPongRallyProps = Record<string, any>;

const PingPongRally: React.FC<PingPongRallyProps> = ({
  backgroundColor = "#222222",
  tableColor = "#1e8e3e",
  netColor = "#ffffff",
  batColorLeft = "#d32f2f",
  batColorRight = "#1976d2",
  ballColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  rallySpeed = 1.5,
  ballSize = 25,
}) => {
  useFontLoader(["Roboto"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // --- Constants & Layout ---
  const tableWidth = width * 0.8;
  const tableHeight = height * 0.6;
  const tableX = (width - tableWidth) / 2;
  const tableY = (height - tableHeight) / 2;

  const batWidth = 20;
  const batHeight = 100;
  const batOffset = 40; // Distance from table edge

  // --- Animation Logic ---
  // One complete cycle (Left -> Right -> Left)
  const cycleDurationFrames = Math.floor(fps * rallySpeed);
  
  // Current progress within the cycle [0, 1]
  const rawProgress = (frame % cycleDurationFrames) / cycleDurationFrames;
  
  // Ball X Movement
  // 0 -> 0.5: Left to Right
  // 0.5 -> 1.0: Right to Left
  const ballXProgress = interpolate(
    rawProgress,
    [0, 0.5, 1],
    [0, 1, 0],
    {
      easing: Easing.linear, // Constant horizontal speed looks best for top-down ping pong
    }
  );

  const leftBatX = tableX - batOffset;
  const rightBatX = tableX + tableWidth + batOffset - batWidth;
  
  // Calculate actual ball X position
  const ballX = interpolate(
    ballXProgress,
    [0, 1],
    [leftBatX + batWidth, rightBatX - ballSize]
  );

  // Ball Y Movement (Adding some spin/curve)
  // We simulate the ball targeting different spots on the table to make the bats move
  // Using a sine wave for Y position to create a weaving pattern
  const verticalOscillation = Math.sin(frame * 0.05) * (tableHeight * 0.3);
  const ballY = (height / 2) - (ballSize / 2) + verticalOscillation;

  // Ball Scale (Simulating Bounce/Arc Height)
  // In a cycle (Left -> Right), the ball bounces once in the middle? 
  // Or air-to-air? Let's do a bounce on the table.
  // 0 -> 0.25 (Left to Net), 0.25 -> 0.5 (Net to Right)
  // High at 0, Low (bounce) at 0.25, High at 0.5
  const bouncePhase = (rawProgress * 2) % 1; // 0->1 twice per full cycle
  
  // Parabolic arc for height/scale: 4 * x * (1-x) is a simple parabola 0->1->0
  // But here we want High -> Low -> High for a bounce in middle of travel
  // Actually, let's make it simpler: Large at bats, small at net (bounce)
  const arcHeight = Math.abs(Math.cos(rawProgress * Math.PI * 2)); // 1 at ends, 0 in middle
  
  // Refined Scale: 
  // 1.0 = Table level (bounce)
  // 1.5 = Peak height
  const ballScale = interpolate(
    arcHeight,
    [0, 1],
    [0.8, 1.4], // Smaller at net (bounce), larger at bats
    { easing: Easing.quad }
  );
  
  // Shadow opacity (stronger when ball is close to table/smaller)
  const shadowOpacity = interpolate(
    ballScale,
    [0.8, 1.4],
    [0.8, 0.2]
  );


  // --- Bat Movement ---
  // Bats track the ball Y, but with a slight delay or anticipation
  // We clamp the bat movement to the table height area
  const clampBatY = (y: number) => {
    const min = tableY - batHeight / 2;
    const max = tableY + tableHeight - batHeight / 2;
    return Math.min(Math.max(y, min), max);
  };

  // Simple tracking: Bats Center Y = Ball Center Y
  // Add some lag using a delayed version of 'frame' or just direct tracking for crispness
  const targetBatY = ballY + (ballSize / 2) - (batHeight / 2);
  const batY = clampBatY(targetBatY);

  // Bat Rotation (Impact effect)
  // Rotate slightly when hitting
  // Left hit happens at rawProgress ~ 0 or 1
  // Right hit happens at rawProgress ~ 0.5
  
  // Fix for monotonicity: Split the wrap-around interpolation into two parts
  // Part 1: End of cycle (0.95 -> 1.0)
  const hitSnapLeftPre = interpolate(
    rawProgress,
    [0.95, 1],
    [0, -15],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );
  
  // Part 2: Start of cycle (0.0 -> 0.05)
  const hitSnapLeftPost = interpolate(
    rawProgress,
    [0, 0.05],
    [-15, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  const hitSnapLeft = hitSnapLeftPre + hitSnapLeftPost;

  const hitSnapRight = interpolate(
    rawProgress,
    [0.45, 0.5, 0.55],
    [0, 15, 0], // Rotate clockwise slightly
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );
  
  // Fix interpolation glitch at wrapping point 1->0 for Left Bat
  // We can just use sine of progress for smooth rotation if strictly periodic
  const batRotLeft = rawProgress > 0.9 || rawProgress < 0.1 ? hitSnapLeft : 0;
  const batRotRight = rawProgress > 0.4 && rawProgress < 0.6 ? hitSnapRight : 0;

  // Background handling
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      
      {/* Table Surface */}
      <div
        style={{
          position: "absolute",
          left: tableX,
          top: tableY,
          width: tableWidth,
          height: tableHeight,
          backgroundColor: tableColor,
          borderRadius: 8,
          boxShadow: "0 20px 50px rgba(0,0,0,0.3)",
          border: `4px solid white`
        }}
      >
        {/* Center Line (Net) */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: 0,
            bottom: 0,
            width: 4,
            backgroundColor: `${netColor}80`, // Semi-transparent net
            transform: "translateX(-50%)",
            borderLeft: "2px dashed rgba(255,255,255,0.5)"
          }}
        />
        
        {/* Table Center horizontal line (optional decoration) */}
        <div
            style={{
                position: "absolute",
                top: "50%",
                left: 0,
                right: 0,
                height: 2,
                backgroundColor: "rgba(255,255,255,0.2)",
            }}
        />
      </div>

      {/* Shadows (Rendered before objects) */}
      {/* Left Bat Shadow */}
      <div style={{
          position: "absolute",
          left: leftBatX + 10,
          top: batY + 10,
          width: batWidth,
          height: batHeight,
          backgroundColor: "rgba(0,0,0,0.2)",
          borderRadius: 10,
          transform: `rotate(${batRotLeft}deg)`,
      }} />
      
      {/* Right Bat Shadow */}
      <div style={{
          position: "absolute",
          left: rightBatX + 10,
          top: batY + 10,
          width: batWidth,
          height: batHeight,
          backgroundColor: "rgba(0,0,0,0.2)",
          borderRadius: 10,
          transform: `rotate(${batRotRight}deg)`,
      }} />

      {/* Ball Shadow */}
      <div
        style={{
            position: "absolute",
            left: ballX,
            top: ballY + ballSize * 0.8, // Offset downwards
            width: ballSize,
            height: ballSize * 0.6, // Flattened circle
            backgroundColor: "black",
            borderRadius: "50%",
            opacity: shadowOpacity,
            transform: `scale(${1 / ballScale})`, // Shadow shrinks when ball grows (moves up)
            filter: "blur(4px)",
        }}
      />


      {/* Left Bat */}
      <div
        style={{
          position: "absolute",
          left: leftBatX,
          top: batY,
          width: batWidth,
          height: batHeight,
          backgroundColor: batColorLeft,
          borderRadius: 10,
          border: "2px solid rgba(0,0,0,0.2)",
          transform: `rotate(${batRotLeft}deg)`,
          transformOrigin: "center center",
          zIndex: 10
        }}
      >
        <div style={{ width: "100%", height: "100%", borderRadius: 10, background: "linear-gradient(90deg, rgba(255,255,255,0.2) 0%, rgba(0,0,0,0.1) 100%)"}} />
      </div>

      {/* Right Bat */}
      <div
        style={{
          position: "absolute",
          left: rightBatX,
          top: batY,
          width: batWidth,
          height: batHeight,
          backgroundColor: batColorRight,
          borderRadius: 10,
          border: "2px solid rgba(0,0,0,0.2)",
          transform: `rotate(${batRotRight}deg)`,
          transformOrigin: "center center",
          zIndex: 10
        }}
      >
        <div style={{ width: "100%", height: "100%", borderRadius: 10, background: "linear-gradient(-90deg, rgba(255,255,255,0.2) 0%, rgba(0,0,0,0.1) 100%)"}} />
      </div>

      {/* Ball */}
      <div
        style={{
          position: "absolute",
          left: ballX,
          top: ballY,
          width: ballSize,
          height: ballSize,
          backgroundColor: ballColor,
          borderRadius: "50%",
          transform: `scale(${ballScale})`,
          boxShadow: "inset -2px -2px 6px rgba(0,0,0,0.2)",
          zIndex: 20
        }}
      />

    </AbsoluteFill>
  );
};

export default PingPongRally;